// Generated by /ship test coverage audit.
// Value: protects=readSavedLocation returns null (no crash) when storage is empty, corrupt or blocked, and round-trips a write;
//   fails_when=the try/catch or empty check is removed, so Home and discovery pages throw on load;
//   why_new=e2e only exercises the happy save path with working storage; seam=none
import { afterEach, describe, expect, it, vi } from 'vitest';
import { LOCATION_KEY, readSavedLocation, writeSavedLocation } from './discovery';

describe('saved delivery location', () => {
  afterEach(() => { vi.restoreAllMocks(); localStorage.clear(); });

  it('round-trips a saved location', () => {
    expect(readSavedLocation()).toBeNull();
    const loc = { country: 'Nigeria', city: 'Lagos', address: '12 Herbert Macaulay Way' };
    writeSavedLocation(loc);
    expect(readSavedLocation()).toEqual(loc);
  });

  it('treats corrupt JSON as no saved location', () => {
    localStorage.setItem(LOCATION_KEY, '{not json');
    expect(readSavedLocation()).toBeNull();
  });

  it('survives blocked storage on read and write', () => {
    vi.spyOn(Storage.prototype, 'getItem').mockImplementation(() => { throw new DOMException('blocked', 'SecurityError'); });
    vi.spyOn(Storage.prototype, 'setItem').mockImplementation(() => { throw new DOMException('quota', 'QuotaExceededError'); });
    expect(readSavedLocation()).toBeNull();
    expect(() => writeSavedLocation({ country: 'Nigeria', city: 'Abuja', address: 'x' })).not.toThrow();
  });
});
